  'flows.resource.invalidName': ['Use only letters, digits, _ and -; do not start with a digit.', 'Usa solo letras, dígitos, _ y -; no empieces con un dígito.', 'Verwende nur Buchstaben, Ziffern, _ und -; beginne nicht mit einer Ziffer.', 'Utilisez uniquement des lettres, des chiffres, _ et - ; ne commencez pas par un chiffre.', 'Usa solo lettere, cifre, _ e -; non iniziare con una cifra.', 'Use apenas letras, dígitos, _ e -; não comece com um dígito.', '只能使用字母、数字、_ 和 -；不能以数字开头。'],
  'flows.resource.nameSuggestions': ['Steps reference it as ${res:NAME}. Suggestions are names already used in this flow.', 'Los pasos hacen referencia a él como ${res:NAME}. Las sugerencias son nombres que ya se usan en este flujo.', 'Schritte verweisen mit ${res:NAME} darauf. Die Vorschläge sind bereits in diesem Flow verwendete Namen.', 'Les étapes la référencent avec ${res:NAME}. Les suggestions sont des noms déjà utilisés dans ce flux.', 'I passaggi la richiamano con ${res:NAME}. I suggerimenti sono nomi già usati in questo flusso.', 'As etapas fazem referência com ${res:NAME}. As sugestões são nomes já usados neste fluxo.', '步骤通过 ${res:NAME} 引用。建议项是此流程中已使用的名称。'],
  'flows.resource.nameHelp': ['Steps reference it as ${res:NAME}; a producing edge saves the step output under this name.', 'Los pasos hacen referencia a él como ${res:NAME}; una conexión productora guarda la salida del paso con este nombre.', 'Schritte verweisen mit ${res:NAME} darauf; eine erzeugende Kante speichert die Schrittausgabe unter diesem Namen.', 'Les étapes la référencent avec ${res:NAME} ; une liaison productrice enregistre la sortie de l’étape sous ce nom.', 'I passaggi la richiamano con ${res:NAME}; un collegamento di produzione salva l’output con questo nome.', 'As etapas fazem referência com ${res:NAME}; uma conexão produtora salva a saída da etapa com esse nome.', '步骤通过 ${res:NAME} 引用；生成连接会以此名称保存步骤输出。'],
  'flows.resource.runtimeUri': ['Runtime URI: flujo://run/<conversation>/… (named “{name}”)', 'URI durante la ejecución: flujo://run/<conversación>/… (con el nombre «{name}»)', 'Laufzeit-URI: flujo://run/<gespräch>/… (Name „{name}“)', 'URI lors de l’exécution : flujo://run/<conversation>/… (nommée « {name} »)', 'URI durante l’esecuzione: flujo://run/<conversazione>/… (nome “{name}”)', 'URI durante a execução: flujo://run/<conversa>/… (nome “{name}”)', '运行时 URI：flujo://run/<conversation>/…（名称为“{name}”）'],
