  'flows.process.renderOrder': ['Prompt rendering order:', 'Orden de composición de las instrucciones:', 'Reihenfolge der Anweisungen:', 'Ordre de composition des instructions :', 'Ordine di composizione delle istruzioni:', 'Ordem de composição das instruções:', '提示词渲染顺序：'],
  'flows.process.startPrompt': ['Start node prompt', 'Instrucciones del nodo de inicio', 'Anweisung des Startknotens', 'Instruction du nœud de départ', 'Istruzioni del nodo iniziale', 'Instruções do nó inicial', '开始节点提示词'],
