  'flows.process.modelPrompt': ['Model prompt', 'Instrucciones del modelo', 'Modellanweisung', 'Instruction du modèle', 'Istruzioni del modello', 'Instruções do modelo', '模型提示词'],
  'flows.process.fromModel': ['(from the selected model: {model})', '(del modelo seleccionado: {model})', '(vom ausgewählten Modell: {model})', '(provenant du modèle sélectionné : {model})', '(dal modello selezionato: {model})', '(do modelo selecionado: {model})', '（来自所选模型：{model}）'],
