  'flows.convert.error.target': ['The selected node no longer exists or is not a Process node.', 'El nodo seleccionado ya no existe o no es un nodo de proceso.', 'Der ausgewählte Knoten ist nicht mehr vorhanden oder kein Prozessknoten.', 'Le nœud sélectionné n’existe plus ou n’est pas un nœud de traitement.', 'Il nodo selezionato non esiste più o non è un nodo di elaborazione.', 'O nó selecionado não existe mais ou não é um nó de processo.', '所选节点已不存在或不是处理节点。'],
  'flows.convert.error.nameRequired': ['Enter a name for the new subflow.', 'Escribe un nombre para el nuevo subflujo.', 'Gib einen Namen für den neuen Unterablauf ein.', 'Saisissez un nom pour le nouveau sous-flux.', 'Inserisci un nome per il nuovo flusso secondario.', 'Digite um nome para o novo subfluxo.', '请输入新子流程的名称。'],
  'flows.convert.error.invalidName': ['The subflow name may contain only letters, numbers, underscores, and dashes.', 'El nombre del subflujo solo puede contener letras, números, guiones bajos y guiones.', 'Der Name des Unterablaufs darf nur Buchstaben, Zahlen, Unterstriche und Bindestriche enthalten.', 'Le nom du sous-flux ne peut contenir que des lettres, des chiffres, des traits de soulignement et des tirets.', 'Il nome del flusso secondario può contenere solo lettere, numeri, trattini bassi e trattini.', 'O nome do subfluxo pode conter apenas letras, números, sublinhados e hífens.', '子流程名称只能包含字母、数字、下划线和短横线。'],
  'flows.convert.error.duplicateName': ['An agent named “{name}” already exists.', 'Ya existe un agente llamado «{name}».', 'Ein Agent namens „{name}“ ist bereits vorhanden.', 'Un agent nommé « {name} » existe déjà.', 'Esiste già un agente chiamato “{name}”.', 'Já existe um agente chamado “{name}”.', '已存在名为“{name}”的智能体。'],
  'flows.convert.error.missingEdgeNode': ['Connection “{edge}” points to a missing node. Repair the flow before converting.', 'La conexión «{edge}» apunta a un nodo que falta. Repara el flujo antes de convertir.', 'Verbindung „{edge}“ verweist auf einen fehlenden Knoten. Repariere den Ablauf vor der Umwandlung.', 'La connexion « {edge} » pointe vers un nœud manquant. Réparez le flux avant la conversion.', 'Il collegamento “{edge}” punta a un nodo mancante. Ripara il flusso prima della conversione.', 'A conexão “{edge}” aponta para um nó ausente. Corrija o fluxo antes da conversão.', '连接“{edge}”指向缺失的节点。请先修复流程再进行转换。'],
  'flows.convert.error.attachmentControl': ['{node} is connected as control flow. Reconnect it with its {type} attachment handles before converting.', '{node} está conectado como flujo de control. Vuelve a conectarlo mediante sus conectores de adjunto {type} antes de convertir.', '{node} ist als Kontrollfluss verbunden. Verbinde den Knoten vor der Umwandlung erneut über seine {type}-Anschlüsse.', '{node} est connecté comme flux de contrôle. Reconnectez-le avec ses poignées de pièce jointe {type} avant la conversion.', '{node} è collegato come flusso di controllo. Ricollegalo tramite i connettori {type} prima della conversione.', '{node} está conectado como fluxo de controle. Reconecte-o pelas alças de anexo {type} antes da conversão.', '{node} 已连接为控制流。转换前请使用其 {type} 附件连接点重新连接。'],
  'flows.convert.error.unsupportedAttachment': ['Attachment connection “{edge}” does not connect to an MCP or Resource node.', 'La conexión de adjunto «{edge}» no se conecta a un nodo MCP ni de recurso.', 'Anhangsverbindung „{edge}“ ist nicht mit einem MCP- oder Ressourcenknoten verbunden.', 'La connexion de pièce jointe « {edge} » ne relie pas un nœud MCP ou de ressource.', 'Il collegamento allegato “{edge}” non è connesso a un nodo MCP o risorsa.', 'A conexão de anexo “{edge}” não se conecta a um nó MCP ou de recurso.', '附件连接“{edge}”未连接到 MCP 节点或资源节点。'],
  'flows.convert.error.sharedAttachment': ['Attachment “{edge}” is also used outside the converted region. Duplicate or disconnect it first.', 'El adjunto «{edge}» también se usa fuera de la región convertida. Duplícalo o desconéctalo primero.', 'Anhang „{edge}“ wird auch außerhalb des umzuwandelnden Bereichs verwendet. Dupliziere oder trenne ihn zuerst.', 'La pièce jointe « {edge} » est également utilisée hors de la zone convertie. Dupliquez-la ou déconnectez-la d’abord.', 'L’allegato “{edge}” è usato anche fuori dall’area convertita. Duplicalo o scollegalo prima.', 'O anexo “{edge}” também é usado fora da região convertida. Duplique-o ou desconecte-o primeiro.', '附件“{edge}”也在转换区域之外使用。请先复制或断开该附件。'],
  'flows.convert.error.bidirectional': ['Boundary connection “{edge}” is bidirectional. Make it one-way before converting; internal bidirectional connections are preserved.', 'La conexión de límite «{edge}» es bidireccional. Hazla unidireccional antes de convertir; se conservarán las conexiones bidireccionales internas.', 'Grenzverbindung „{edge}“ ist bidirektional. Stelle sie vor der Umwandlung auf eine Richtung um; interne bidirektionale Verbindungen bleiben erhalten.', 'La connexion de limite « {edge} » est bidirectionnelle. Rendez-la unidirectionnelle avant la conversion ; les connexions bidirectionnelles internes sont conservées.', 'Il collegamento di confine “{edge}” è bidirezionale. Rendilo unidirezionale prima della conversione; i collegamenti bidirezionali interni vengono mantenuti.', 'A conexão de limite “{edge}” é bidirecional. Torne-a unidirecional antes da conversão; conexões bidirecionais internas são preservadas.', '边界连接“{edge}”是双向的。请在转换前改为单向；内部双向连接会保留。'],
  'flows.convert.error.outputs.one': ['This region has {count} distinct parent exit. A subflow supports one outgoing control path; join the branches before converting.', 'Esta región tiene {count} salida principal distinta. Un subflujo admite una ruta de control saliente; une las ramas antes de convertir.', 'Dieser Bereich hat {count} unterschiedlichen übergeordneten Ausgang. Ein Unterablauf unterstützt einen ausgehenden Kontrollpfad; führe die Zweige vor der Umwandlung zusammen.', 'Cette zone possède {count} sortie parent distincte. Un sous-flux prend en charge un chemin de contrôle sortant ; réunissez les branches avant la conversion.', 'Quest’area ha {count} uscita principale distinta. Un flusso secondario supporta un percorso di controllo in uscita; unisci i rami prima della conversione.', 'Esta região tem {count} saída principal distinta. Um subfluxo aceita um caminho de controle de saída; una as ramificações antes da conversão.', '此区域有 {count} 个不同的父级出口。子流程仅支持一条传出控制路径；请在转换前合并分支。'],
